startxref
398
%%EOF`);

      return pdfContent;
    } catch (error) {
      console.error("Error converting HTML to PDF:", error);
      throw new Error("Failed to convert HTML to PDF");
    }
  }

  async generateCFPBPacketPDF(
    complaintText: string,
