import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Printer, Download, FileText, X, Mail } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

interface PrintPreviewModalProps {
  open: boolean;
  onClose: () => void;
  document?: {
    id?: string;
    filename: string;
    recipient?: string;
    sender?: string;
    pages?: number;
    content?: string;
  };
  onSendToClick2Mail?: () => void;
}

export function PrintPreviewModal({ 
  open, 
  onClose, 
  document,
  onSendToClick2Mail
}: PrintPreviewModalProps) {
  const { toast } = useToast();

  const handlePrint = () => {
    toast({
      title: "Print dialog",
      description: "Opening print dialog...",
    });
    window.print();
  };

  const handleDownloadPDF = () => {
    toast({
      title: "Download started",
      description: "Your PDF is being prepared for download.",
    });
  };

  const handleSendToClick2Mail = () => {
    toast({
      title: "Sending to Click2Mail",
      description: "Your document is being sent for physical mailing.",
    });
    onSendToClick2Mail?.();
    onClose();
  };

  const handleOpenChange = (isOpen: boolean) => {
    if (!isOpen) {
      onClose();
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="max-w-6xl h-[90vh] flex flex-col" data-testid="print-preview-modal">
