            </div>
          </div>

          {/* Sidebar */}
          <div className="w-80 space-y-4">
            <div className="bg-gray-50 dark:bg-gray-900 rounded-lg p-4 border">
              <h3 className="font-semibold mb-3">Document Info</h3>
              <div className="space-y-2 text-sm">
                <div>
                  <span className="text-gray-600 dark:text-gray-400">Document:</span>
                  <p className="font-medium">{document?.filename || "Dispute Letter"}</p>
                </div>
                <div>
                  <span className="text-gray-600 dark:text-gray-400">Pages:</span>
                  <p className="font-medium">{document?.pages || 1}</p>
                </div>
                <div>
                  <span className="text-gray-600 dark:text-gray-400">Recipient:</span>
                  <p className="font-medium">{document?.recipient || "Credit Bureau"}</p>
                </div>
              </div>
            </div>

            <div className="space-y-3">
              <Button
                onClick={handleSendToClick2Mail}
                className="w-full"
                size="lg"
                data-testid="send-to-click2mail"
              >
                <Mail className="h-4 w-4 mr-2" />
                Send via Click2Mail
              </Button>

              <Button
                onClick={handlePrint}
                variant="outline"
                className="w-full"
                size="lg"
                data-testid="print-button"
              >
                <Printer className="h-4 w-4 mr-2" />
                Print Document
              </Button>

              <Button
                onClick={handleDownloadPDF}
                variant="outline"
                className="w-full"
                size="lg"
                data-testid="download-pdf"
              >
                <Download className="h-4 w-4 mr-2" />
                Download PDF
              </Button>
            </div>

            <div className="bg-blue-50 dark:bg-blue-950 rounded-lg p-4 border border-blue-200 dark:border-blue-800">
              <div className="flex items-start gap-2">
                <FileText className="h-5 w-5 text-blue-600 dark:text-blue-400 flex-shrink-0 mt-0.5" />
                <div className="text-sm">
                  <p className="font-medium text-blue-900 dark:text-blue-100 mb-1">Tip</p>
                  <p className="text-blue-700 dark:text-blue-300">
                    Sending via Click2Mail will mail this document using certified mail with tracking.
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

scripts/copy-build-assets.ts.content:
#!/usr/bin/env tsx
/**
 * Copy non-TypeScript assets to dist/ directory after build
 * This ensures openapi.yml is available in production builds
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, '..');

console.log('📦 Copying build assets...');

// Ensure dist directory exists
const distDir = path.join(rootDir, 'dist');
if (!fs.existsSync(distDir)) {
  fs.mkdirSync(distDir, { recursive: true });
}

// Copy openapi.yml to dist/
const openapiSource = path.join(rootDir, 'server', 'openapi.yml');
const openapiDest = path.join(distDir, 'openapi.yml');

try {
  fs.copyFileSync(openapiSource, openapiDest);
  console.log('✅ Copied server/openapi.yml → dist/openapi.yml');
} catch (error) {
  console.error('❌ Failed to copy openapi.yml:', error);
  process.exit(1);
}

console.log('✅ Build assets copied successfully!');

client/src/pages/profile.tsx.content:
import { useState, useEffect } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { User as UserIcon, FileText, Crown, Save, Mail } from "lucide-react";
import type { User, CreditReport, DisputeLetter } from "@shared/schema";

export default function ProfilePage() {
  const { toast } = useToast();

  const { data: user, isLoading: userLoading } = useQuery<User>({
    queryKey: ["/api/auth/user"],
  });

  const { data: creditReports, isLoading: reportsLoading } = useQuery<CreditReport[]>({
    queryKey: ["/api/credit-reports"],
  });

  const { data: disputeLetters, isLoading: lettersLoading } = useQuery<DisputeLetter[]>({
    queryKey: ["/api/dispute-letters"],
  });

  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");

  useEffect(() => {
    if (user) {
      setFirstName(user.firstName || "");
      setLastName(user.lastName || "");
    }
  }, [user]);

  const updateProfileMutation = useMutation({
    mutationFn: async (data: { firstName: string; lastName: string }) => {
      return await apiRequest("PATCH", "/api/auth/profile", data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/auth/user"] });
      toast({
        title: "Profile Updated",
        description: "Your profile has been updated successfully.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Update Failed",
        description: error.message || "Failed to update profile",
        variant: "destructive",
      });
    },
  });

  const handleSaveProfile = () => {
    updateProfileMutation.mutate({ firstName, lastName });
  };

  if (userLoading) {
    return (
      <div className="container mx-auto p-6 max-w-5xl">
        <div className="space-y-6 animate-pulse">
          <div className="h-8 bg-gray-200 dark:bg-gray-700 rounded w-1/4"></div>
          <div className="h-64 bg-gray-200 dark:bg-gray-700 rounded"></div>
        </div>
      </div>
    );
  }

  const planInfo = {
    DIY: {
      name: "DIY Plan",
      price: "$19.95/month",
      features: ["Credit report analysis", "AI-powered violation detection", "Letter generation", "Self-service tools"],
      color: "bg-blue-100 dark:bg-blue-900 text-blue-800 dark:text-blue-200",
    },
    DONE_FOR_YOU: {
      name: "Done-For-You Plan",
      price: "$149.99/month",
      features: ["All DIY features", "Automated certified mail delivery", "Bureau response tracking", "Priority support"],
      color: "bg-purple-100 dark:bg-purple-900 text-purple-800 dark:text-purple-200",
    },
    ENTERPRISE: {
      name: "Enterprise Plan",
      price: "Custom pricing",
      features: ["All Done-For-You features", "Dedicated account manager", "Custom integrations", "White-label options"],
      color: "bg-amber-100 dark:bg-amber-900 text-amber-800 dark:text-amber-200",
    },
  };

  const currentPlan = planInfo[user?.plan as keyof typeof planInfo] || planInfo.DIY;

  return (
    <div className="container mx-auto p-6 max-w-5xl space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-2">
            <UserIcon className="h-8 w-8" />
            User Profile
          </h1>
          <p className="text-muted-foreground mt-1">
            Manage your account settings and view your activity
          </p>
        </div>
      </div>

      <div className="grid md:grid-cols-2 gap-6">
        {/* Profile Settings */}
        <Card data-testid="profile-settings-card">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <UserIcon className="h-5 w-5" />
              Profile Settings
            </CardTitle>
            <CardDescription>Update your personal information</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                value={user?.email || ""}
                disabled
                className="bg-gray-50 dark:bg-gray-900"
                data-testid="profile-email"
              />
              <p className="text-xs text-muted-foreground">
                Email cannot be changed (managed by Replit Auth)
              </p>
            </div>

            <div className="space-y-2">
              <Label htmlFor="firstName">First Name</Label>
              <Input
                id="firstName"
                type="text"
                value={firstName}
                onChange={(e) => setFirstName(e.target.value)}
                placeholder={user?.firstName || "Enter first name"}
                data-testid="profile-firstname-input"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="lastName">Last Name</Label>
              <Input
                id="lastName"
                type="text"
                value={lastName}
                onChange={(e) => setLastName(e.target.value)}
                placeholder={user?.lastName || "Enter last name"}
                data-testid="profile-lastname-input"
              />
            </div>

            <Button
              onClick={handleSaveProfile}
              disabled={updateProfileMutation.isPending}
              className="w-full"
              data-testid="profile-save-btn"
            >
              <Save className="h-4 w-4 mr-2" />
              {updateProfileMutation.isPending ? "Saving..." : "Save Profile"}
            </Button>
          </CardContent>
        </Card>

        {/* Account Tier */}
        <Card data-testid="account-tier-card">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Crown className="h-5 w-5" />
              Account Tier
            </CardTitle>
            <CardDescription>Your current subscription plan</CardDescription>
          </CardHeader>
          <CardContent>
            <div className={`p-4 rounded-lg ${currentPlan.color} space-y-3`}>
              <div className="flex items-center justify-between">
                <h3 className="text-xl font-semibold">{currentPlan.name}</h3>
                <Badge variant="secondary" className="text-xs">
                  {currentPlan.price}
                </Badge>
              </div>

              <Separator className="bg-current opacity-20" />

              <div className="space-y-2">
                <p className="font-medium text-sm">Features:</p>
                <ul className="space-y-1">
                  {currentPlan.features.map((feature, idx) => (
                    <li key={idx} className="text-sm flex items-start gap-2">
                      <span className="mt-0.5">✓</span>
                      <span>{feature}</span>
                    </li>
                  ))}
                </ul>
              </div>

              {user?.role === "admin" && (
                <Badge variant="destructive" className="mt-3">
                  Admin Account
                </Badge>
              )}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Saved Documents */}
      <Card data-testid="saved-documents-card">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileText className="h-5 w-5" />
            Saved Documents
          </CardTitle>
          <CardDescription>Your uploaded credit reports and generated letters</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {/* Credit Reports */}
            <div>
              <h4 className="font-medium mb-2 flex items-center gap-2">
                Credit Reports ({creditReports?.length || 0})
              </h4>
              {reportsLoading ? (
                <div className="text-sm text-muted-foreground">Loading...</div>
              ) : creditReports && creditReports.length > 0 ? (
                <ul className="space-y-2 bg-gray-50 dark:bg-gray-900 p-4 rounded-lg">
                  {creditReports.slice(0, 5).map((report: any) => (
                    <li
                      key={report.id}
                      className="flex items-center justify-between text-sm"
                      data-testid={`saved-report-${report.id}`}
                    >
                      <span className="flex items-center gap-2">
                        <FileText className="h-4 w-4 text-blue-500" />
                        {report.fileName}
                      </span>
                      <Badge variant="outline" className="text-xs">
                        {report.bureau || "Unknown"}
                      </Badge>
                    </li>
                  ))}
                  {creditReports.length > 5 && (
                    <li className="text-xs text-muted-foreground pt-2">
                      ... and {creditReports.length - 5} more
                    </li>
                  )}
                </ul>
              ) : (
                <p className="text-sm text-muted-foreground bg-gray-50 dark:bg-gray-900 p-4 rounded-lg">
                  No credit reports uploaded yet
                </p>
              )}
            </div>

            <Separator />

            {/* Dispute Letters */}
            <div>
              <h4 className="font-medium mb-2 flex items-center gap-2">
                Dispute Letters ({disputeLetters?.length || 0})
              </h4>
              {lettersLoading ? (
                <div className="text-sm text-muted-foreground">Loading...</div>
              ) : disputeLetters && disputeLetters.length > 0 ? (
                <ul className="space-y-2 bg-gray-50 dark:bg-gray-900 p-4 rounded-lg">
                  {disputeLetters.slice(0, 5).map((letter: any) => (
                    <li
                      key={letter.id}
                      className="flex items-center justify-between text-sm"
                      data-testid={`saved-letter-${letter.id}`}
                    >
                      <span className="flex items-center gap-2">
                        <Mail className="h-4 w-4 text-purple-500" />
                        {letter.letterType} - {letter.bureau}
                      </span>
                      <Badge variant="outline" className="text-xs">
                        {letter.status}
                      </Badge>
                    </li>
                  ))}
                  {disputeLetters.length > 5 && (
                    <li className="text-xs text-muted-foreground pt-2">
                      ... and {disputeLetters.length - 5} more
                    </li>
                  )}
                </ul>
              ) : (
                <p className="text-sm text-muted-foreground bg-gray-50 dark:bg-gray-900 p-4 rounded-lg">
                  No dispute letters generated yet
                </p>
              )}
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

server/stripeWebhook.ts.content:
import express, { type Express } from "express";
import Stripe from "stripe";
import { storage } from "./storage";
import { notificationService } from "./services/notificationService";

const stripe = process.env.STRIPE_SECRET_KEY 
  ? new Stripe(process.env.STRIPE_SECRET_KEY, {
      apiVersion: '2025-08-27.basil',
    })
  : null;

export function registerStripeWebhook(app: Express) {
  app.post(
    '/api/stripe/webhook',
    express.raw({ type: 'application/json' }),
    async (req, res) => {
      if (!stripe) {
        console.error('Stripe not configured - STRIPE_SECRET_KEY missing');
        return res.status(503).send('Stripe not configured');
      }

      const sig = req.headers['stripe-signature'];
      if (!sig) {
        console.error('Missing stripe-signature header');
        return res.status(400).send('Missing stripe-signature header');
      }

      const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET_SNAPSHOT || 
                           process.env.STRIPE_WEBHOOK_SECRET_THIN;

      if (!webhookSecret) {
        console.error('Stripe webhook secret not configured - add STRIPE_WEBHOOK_SECRET_SNAPSHOT or STRIPE_WEBHOOK_SECRET_THIN');
        return res.status(503).send('Webhook secret not configured');
      }

      let event: Stripe.Event;

      try {
        event = stripe.webhooks.constructEvent(
          req.body,
          sig,
          webhookSecret
        );
      } catch (err: any) {
        console.error('❌ Webhook signature verification failed:', err.message);
        return res.status(400).send(`Webhook Error: ${err.message}`);
      }

      console.log(`✓ Stripe webhook received: ${event.type}`);

      try {
        switch (event.type) {
          case 'checkout.session.completed': {
            const session = event.data.object as Stripe.Checkout.Session;
            const customerEmail = session.customer_email || session.customer_details?.email;
            const customerId = session.customer as string;
            const subscriptionId = session.subscription as string;

            if (customerEmail && customerId) {
              const user = await storage.getUserByEmail(customerEmail);
              if (user) {
                await storage.updateUserStripeInfo(user.id, customerId, subscriptionId);
                await storage.updateUserPlan(user.id, "DONE_FOR_YOU");
                console.log(`✓ User ${user.email} upgraded to DONE_FOR_YOU via Stripe`);

                if (user.email) {
                  await notificationService.sendUpgradeConfirmation(
                    user.email,
                    user.firstName || 'User'
                  );
                }
              }
            }
            break;
          }

          case 'invoice.paid': {
            const invoice = event.data.object as Stripe.Invoice;
            const customerEmail = invoice.customer_email;

            if (customerEmail) {
              const user = await storage.getUserByEmail(customerEmail);
              if (user) {
                console.log(`✓ Invoice paid for user ${user.email}`);
              }
            }
            break;
          }

          case 'invoice.payment_failed': {
            const invoice = event.data.object as Stripe.Invoice;
            const customerEmail = invoice.customer_email;

            if (customerEmail) {
              const user = await storage.getUserByEmail(customerEmail);
              if (user && user.email) {
                console.log(`⚠ Payment failed for user ${user.email}`);
              }
            }
            break;
          }

          case 'customer.subscription.deleted': {
            const subscription = event.data.object as Stripe.Subscription;
            const customerId = subscription.customer as string;

            const users = await storage.getAllUsers();
            const user = users.find(u => u.stripeCustomerId === customerId);

            if (user) {
              await storage.updateUserPlan(user.id, "DIY");
              console.log(`✓ User ${user.email} downgraded to DIY due to subscription cancellation`);
            }
            break;
          }

          default:
            console.log(`Unhandled Stripe event type: ${event.type}`);
        }

        res.json({ received: true });
      } catch (error) {
        console.error('❌ Error processing webhook:', error);
        res.status(500).json({ error: 'Webhook processing failed' });
      }
    }
  );
}

server/click2mailWebhook.ts.content:
import express, { type Express } from "express";
import crypto from "crypto";
import { db } from "./db";
import { mailBatches, deliveryEvents, users } from "@shared/schema";
import { eq } from "drizzle-orm";
import { notificationService } from "./services/notificationService";

export function registerClick2MailWebhook(app: Express) {
  app.post(
    '/webhooks/click2mail',
    express.raw({ type: 'application/json' }),
    async (req, res) => {
      try {
        // Verify that we received a raw buffer body
        if (!Buffer.isBuffer(req.body)) {
          console.warn('Webhook received non-buffer body - content-type may be incorrect');
          return res.status(415).json({ error: 'Unsupported Media Type - expected application/json' });
        }

        // Verify webhook authenticity using shared secret
        const webhookSecret = process.env.CLICK2MAIL_WEBHOOK_SECRET;
        if (webhookSecret) {
          const signature = req.headers['x-click2mail-signature'] as string;

          if (!signature) {
            console.warn('Missing x-click2mail-signature header');
            return res.status(401).json({ error: 'Unauthorized - missing signature' });
          }

          // Compute HMAC of raw body
          const computedSignature = crypto
            .createHmac('sha256', webhookSecret)
            .update(req.body)
            .digest('hex');

          if (signature !== computedSignature) {
            console.warn('Invalid webhook signature');
            return res.status(401).json({ error: 'Unauthorized - invalid signature' });
          }
        } else {
          console.warn('CLICK2MAIL_WEBHOOK_SECRET not configured - webhook is unauthenticated');
        }

        // Parse the JSON body
        const body = JSON.parse(req.body.toString());
        const { jobId, event, tracking, proofUrl } = body;

        // Validate inputs
        if (!jobId || !event) {
          return res.status(400).json({ error: 'Missing required fields: jobId and event' });
        }

        // Find the mail batch
        const batches = await db.select().from(mailBatches).where(eq(mailBatches.click2mailJobId, jobId));
        const batch = batches[0];

        if (batch) {
          // Record delivery event
          await db.insert(deliveryEvents).values({
            id: crypto.randomUUID(),
            batchId: batch.id,
            kind: event,
            payload: body,
            createdAt: new Date()
          });

          // Update batch status and tracking info
          const updates: any = {};
          if (tracking) updates.uspsTracking = tracking;
          if (proofUrl) updates.proofUrl = proofUrl;
          if (event === "delivered") updates.status = "delivered";
          else if (event === "in_transit") updates.status = "in_transit";

          if (Object.keys(updates).length > 0) {
            await db.update(mailBatches).set(updates).where(eq(mailBatches.id, batch.id));
          }

          // Notify client if delivered with proof
          if (proofUrl && batch.clientId) {
            const client = (await db.select().from(users).where(eq(users.id, batch.clientId)))[0];
            if (client?.email) {
              await notificationService.sendEmail(
                client.email,
                "Dispute Letter Delivered",
                `Your dispute letter to ${batch.bureau} has been delivered. <a href="${proofUrl}">View proof of delivery</a>`
              );
            }
          }
        }

        res.json({ success: true });
      } catch (err: any) {
        console.error("Click2Mail webhook error:", err);
        res.status(500).json({ error: err.message });
      }
    }
  );
}
